def find_reversal_indices(cards):
    n = len(cards)
    left = -1
    right = -1
    min_val = float('inf')
    max_val = float('-inf')

    for i in range(n - 1):
        if cards[i] > cards[i + 1]:
            if left == -1:
                left = i
                max_val = cards[i]
            else:
                right = i + 1
                min_val = min(min_val, cards[i + 1])

    if left == -1 or right == -1:
        return "impossible"

    for i in range(left, right + 1):
        if cards[i] < max_val or (i < n - 1 and cards[i] > cards[i + 1]):
            return "impossible"

    for i in range(right + 1, n):
        if cards[i] < min_val:
            return "impossible"

    return f"{left + 1} {right + 1}"

# Example usage:
import sys
input = sys.stdin.read
data = input().split()
n = int(data[0])
cards = list(map(int, data[1:]))

result = find_reversal_indices(cards)
print(result)
